const root = createScene();
root.updateMatrixWorld(true);

const blenderFix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
const blenderNormalMatrix = new THREE.Matrix3().getNormalMatrix(blenderFix);

let obj = '';
let vertexOffset = 1;

function format(n) {
  return Number.isInteger(n) ? String(n) : n.toFixed(6).replace(/\.0+$/,'').replace(/0+$/,'').replace(/\.$/,'');
}

function emitGeometry(name, geometry, matrixWorld) {
  const g = geometry.clone();
  if (!g.attributes.position) return;
  const nonIndexed = g.toNonIndexed();
  const pos = nonIndexed.attributes.position;
  const normalAttr = nonIndexed.attributes.normal;

  const finalMatrix = new THREE.Matrix4().multiplyMatrices(blenderFix, matrixWorld);
  const normalMatrix = new THREE.Matrix3().getNormalMatrix(finalMatrix);

  obj += `o ${name}\n`;
  obj += `g ${name}\n`;

  const verts = [];
  const norms = [];
  for (let i = 0; i < pos.count; i++) {
    const v = new THREE.Vector3().fromBufferAttribute(pos, i).applyMatrix4(finalMatrix);
    verts.push(v);
    obj += `v ${format(v.x)} ${format(v.y)} ${format(v.z)}\n`;
  }
  if (normalAttr) {
    for (let i = 0; i < normalAttr.count; i++) {
      const n = new THREE.Vector3().fromBufferAttribute(normalAttr, i).applyMatrix3(normalMatrix).normalize();
      norms.push(n);
      obj += `vn ${format(n.x)} ${format(n.y)} ${format(n.z)}\n`;
    }
  }
  for (let i = 0; i < pos.count; i += 3) {
    const a = vertexOffset + i;
    const b = vertexOffset + i + 1;
    const c = vertexOffset + i + 2;
    if (normalAttr) obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
    else obj += `f ${a} ${b} ${c}\n`;
  }
  vertexOffset += pos.count;
}

function traverse(node, parentMatrix = new THREE.Matrix4()) {
  const world = new THREE.Matrix4().multiplyMatrices(parentMatrix, node.matrix);
  if (node.isMesh && node.geometry) {
    emitGeometry(node.name || node.type, node.geometry, world);
  } else if (node.isInstancedMesh && node.geometry) {
    const m = new THREE.Matrix4();
    for (let i = 0; i < node.count; i++) {
      node.getMatrixAt(i, m);
      const instWorld = new THREE.Matrix4().multiplyMatrices(world, m);
      emitGeometry(`${node.name || 'InstancedMesh'}_${i}`, node.geometry, instWorld);
    }
  }
  for (const child of node.children || []) {
    traverse(child, world);
  }
}

obj += `# Exported from three.js scene\n`;
traverse(root);
fs.writeFileSync('/root/output/object.obj', obj, 'utf8');
console.log('Wrote /root/output/object.obj');
"}

